export interface OrderBranchContacts {
    phone?: string | null;
}
export interface OrderBranchLocation {
    lat: string | number;
    lng: string | number;
}
export interface OrderBranchWorkingHourSlot {
    from: string;
    to: string;
}
export interface OrderBranchWorkingHour {
    name: string;
    times: OrderBranchWorkingHourSlot[];
}
export interface OrderBranchPreparationTimeRange {
    from: {
        value: number | string;
        unit: string;
    };
    to: {
        value: number | string;
        unit: string;
    };
}
export interface OrderBranch {
    id?: number | string;
    name?: string | null;
    location?: OrderBranchLocation | null;
    contacts?: string | OrderBranchContacts | null;
    preparation_time_range?: OrderBranchPreparationTimeRange | null;
    working_hours?: OrderBranchWorkingHour[] | null;
    always_open?: boolean | number | string | null;
    address?: string | null;
}
export interface NormalizedBranchCoordinates {
    lat: string;
    lng: string;
}
